import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNext()) {
            String s = scanner.next();
            int length = s.length();
            StringBuilder output = new StringBuilder();
            output.append(s.charAt(0));
            int index = 1;
            int flag = 0;
            while (index < length) {
                if (flag == 0 && index < length - 2) {
                    String subStr = s.substring(index, index + 2);
                    if (subStr.equals("at")) {
                        output.append('@');
                        index += 2;
                        flag++;
                        continue;
                    }
                }
                if (index + 3 <= length) {
                    String subStr3 = s.substring(index, index + 3);
                    if (subStr3.equals("dot")) {
                        output.append('.');
                        index += 3;
                        continue;
                    }
                }
                output.append(s.charAt(index));
                index++;
            }
            System.out.print(output.toString());
        }
        scanner.close();
    }
}
